import json, pandas as pd
from pathlib import Path

m=json.loads(Path('/app/output/metrics.json').read_text())
df=pd.read_csv('/app/benchmark/data.csv')
df['Date']=pd.to_datetime(df['Date'])
df=df.sort_values('Date')

def pct(x): return f"{x*100:.2f}%"
def usd(x): return f"${x:,.2f}"
def num(x): return f"{x:,.0f}"

yearly=pd.DataFrame(m['yearly'])
yearly=yearly.sort_values('Year')

# phase inference from local extrema over monthly data
mth=df.set_index('Date')['Close'].resample('M').last().dropna()

html=f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Nike Inc. (NKE) Historical Stock Performance Analysis</title>
<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
<style>
body{{font-family:Inter,Segoe UI,Arial,sans-serif;background:#f5f7fb;color:#1f2937;margin:0}}
.container{{max-width:1200px;margin:0 auto;padding:24px}}
.card{{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 1px 2px rgba(0,0,0,.03)}}
h1{{margin:0 0 8px 0;font-size:30px}} h2{{margin:0 0 10px 0;font-size:22px}}
.sub{{color:#6b7280;margin-bottom:14px}}
.kpi-grid{{display:grid;grid-template-columns:repeat(5,minmax(160px,1fr));gap:10px}}
.kpi{{background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px}}
.kpi .label{{font-size:12px;color:#6b7280}} .kpi .val{{font-size:22px;font-weight:700;margin-top:6px}}
table{{width:100%;border-collapse:collapse;font-size:13px}} th,td{{border-bottom:1px solid #e5e7eb;padding:8px;text-align:right}} th:first-child,td:first-child{{text-align:left}}
.note{{font-size:12px;color:#6b7280}}
</style>
</head>
<body>
<div class="container">
  <div class="card">
    <h1>Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)</h1>
    <div class="sub">Coverage: {m['start_date']} to {m['end_date']} • Audience: Investors • Tone: Analytical, data-forward, professional</div>
    <div class="kpi-grid">
      <div class="kpi"><div class="label">Cumulative Return</div><div class="val">{pct(m['cum_return'])}</div></div>
      <div class="kpi"><div class="label">CAGR</div><div class="val">{pct(m['cagr'])}</div></div>
      <div class="kpi"><div class="label">Maximum Drawdown</div><div class="val">{pct(m['max_dd'])}</div></div>
      <div class="kpi"><div class="label">Avg Daily Volume</div><div class="val">{num(m['avg_vol'])}</div></div>
      <div class="kpi"><div class="label">Annualized Volatility</div><div class="val">{pct(m['ann_vol'])}</div></div>
    </div>
  </div>

  <div class="card"><h2>Executive Summary</h2>
    <p>From {m['start_date']} ({usd(m['start_close'])}) to {m['end_date']} ({usd(m['end_close'])}), NKE delivered a cumulative price return of <b>{pct(m['cum_return'])}</b>, equivalent to a <b>{pct(m['cagr'])}</b> annualized rate. The stock experienced a maximum peak-to-trough drawdown of <b>{pct(m['max_dd'])}</b> (peak: {m['max_dd_peak_date']}, trough: {m['max_dd_date']}). Over the full sample, annualized daily-return volatility was <b>{pct(m['ann_vol'])}</b>.</p>
    <p>Extremes in the sample: all-time low close of <b>{usd(m['atl_close'])}</b> on <b>{m['atl_date']}</b> and all-time high close of <b>{usd(m['ath_close'])}</b> on <b>{m['ath_date']}</b>. Best calendar-year return: <b>{m['best_year']}</b> ({pct(m['best_year_return'])}); worst calendar-year return: <b>{m['worst_year']}</b> ({pct(m['worst_year_return'])}).</p>
  </div>

  <div class="card"><h2>Long-Term Price Trend Analysis</h2><div id="price_chart" style="height:460px"></div>
  <p>The long-horizon trend is upward but non-linear, with distinct accumulation, re-rating, and drawdown regimes. Major de-risking episodes are visible as deep retracements relative to prior highs. The high-water mark at {m['ath_date']} and historical floor at {m['atl_date']} define the full valuation envelope observed in this dataset.</p>
  </div>

  <div class="card"><h2>Volatility and Risk Assessment</h2><div id="vol_chart" style="height:390px"></div>
  <p>Risk is time-varying rather than constant. Rolling 63-trading-day annualized volatility highlights clustered stress periods where realized risk rises materially above baseline. Maximum drawdown reached {pct(m['max_dd'])}, underscoring that even long-run compounders can experience severe interim capital impairment.</p></div>

  <div class="card"><h2>Trading Volume Patterns</h2><div id="volume_chart" style="height:370px"></div>
  <p>Volume spikes generally align with outsized daily price moves, indicating event-driven repricing and liquidity demand. Era averages show changing participation across market regimes: 2000–2006 ({num(m['era_vol']['2000-2006'])}), 2007–2012 ({num(m['era_vol']['2007-2012'])}), 2013–2019 ({num(m['era_vol']['2013-2019'])}), and 2020–2026 ({num(m['era_vol']['2020-2026'])}) shares/day.</p>
  </div>

  <div class="card"><h2>Annual and Decade-Level Performance Breakdown</h2>
    <div id="annual_bar" style="height:360px"></div>
    <table><thead><tr><th>Year</th><th>Start Close</th><th>End Close</th><th>Annual Return</th><th>Avg Volume</th></tr></thead><tbody>
    {''.join([f"<tr><td>{int(r['Year'])}</td><td>{usd(r['start'])}</td><td>{usd(r['end'])}</td><td>{pct(r['return'])}</td><td>{num(r['avg_vol'])}</td></tr>" for _,r in yearly.iterrows()])}
    </tbody></table>
  </div>

  <div class="card"><h2>Key Takeaways and Investment Implications</h2>
    <ul>
      <li>NKE exhibits long-run compounding characteristics ({pct(m['cagr'])} CAGR) with meaningful cyclical drawdown risk ({pct(m['max_dd'])} max drawdown).</li>
      <li>Risk is path-dependent: realized volatility clusters during stress windows rather than staying uniform over time.</li>
      <li>Volume surges coincide with larger daily repricing, reinforcing the need for execution discipline during event-heavy periods.</li>
      <li>For long-horizon investors, historical outcomes suggest returns were earned alongside substantial interim mark-to-market variability.</li>
    </ul>
    <p class="note">All figures are derived exclusively from <code>/app/benchmark/data.csv</code>. Returns are based on the Close column and exclude dividends, taxes, fees, and transaction costs.</p>
  </div>
</div>

<script>
const raw = {df.to_json(orient='records',date_format='iso')};
const dates = raw.map(d=>d.Date);
const close = raw.map(d=>d.Close);
const high = raw.map(d=>d.High);
const low = raw.map(d=>d.Low);
const vol = raw.map(d=>d.Volume);

const ret = close.map((v,i)=> i===0 ? null : (v/close[i-1]-1));
let rolling=[]; for(let i=0;i<ret.length;i++){{
  if(i<63||ret.slice(i-62,i+1).includes(null)){{rolling.push(null);continue;}}
  const arr=ret.slice(i-62,i+1);
  const mean=arr.reduce((a,b)=>a+b,0)/arr.length;
  const sd=Math.sqrt(arr.reduce((a,b)=>a+(b-mean)**2,0)/(arr.length-1));
  rolling.push(sd*Math.sqrt(252));
}}

Plotly.newPlot('price_chart',[
  {{x:dates,y:close,type:'scatter',mode:'lines',name:'Close',line:{{color:'#1f77b4',width:2}}}},
],{{margin:{{t:20,r:20,b:40,l:60}},paper_bgcolor:'#fff',plot_bgcolor:'#fff',xaxis:{{title:'Date'}},yaxis:{{title:'Close (USD)'}}}});

Plotly.newPlot('vol_chart',[
  {{x:dates,y:rolling,type:'scatter',mode:'lines',name:'63D Ann. Vol',line:{{color:'#b91c1c',width:2}}}},
  {{x:dates,y:high.map((h,i)=>(h-low[i])/close[i]),type:'scatter',mode:'lines',name:'Daily Range / Close',line:{{color:'#6b7280',width:1}},yaxis:'y2'}}
],{{margin:{{t:20,r:50,b:40,l:60}},xaxis:{{title:'Date'}},yaxis:{{title:'Annualized Volatility'}},yaxis2:{{title:'Range Ratio',overlaying:'y',side:'right'}},legend:{{orientation:'h'}},paper_bgcolor:'#fff',plot_bgcolor:'#fff'}});

Plotly.newPlot('volume_chart',[
  {{x:dates,y:vol,type:'bar',name:'Volume',marker:{{color:'#64748b'}}}},
  {{x:dates,y:close,type:'scatter',mode:'lines',name:'Close',line:{{color:'#2563eb',width:2}},yaxis:'y2'}}
],{{margin:{{t:20,r:55,b:40,l:60}},xaxis:{{title:'Date'}},yaxis:{{title:'Volume'}},yaxis2:{{title:'Close (USD)',overlaying:'y',side:'right'}},legend:{{orientation:'h'}},paper_bgcolor:'#fff',plot_bgcolor:'#fff'}});

const yearly = {yearly.to_json(orient='records')};
Plotly.newPlot('annual_bar',[
  {{x:yearly.map(d=>d.Year),y:yearly.map(d=>d['return']*100),type:'bar',marker:{{color:yearly.map(d=>d['return']>=0?'#16a34a':'#dc2626')}}}}
],{{margin:{{t:20,r:20,b:40,l:60}},xaxis:{{title:'Year'}},yaxis:{{title:'Return (%)'}},paper_bgcolor:'#fff',plot_bgcolor:'#fff'}});
</script>
</body></html>'''

Path('/app/output/final_report.html').write_text(html)
print('/app/output/final_report.html written')
